def popcountDepth(n, k):
    from math import comb

    def depth(x):
        d = 0
        while x != 1:
            x = bin(x).count('1')
            d += 1
        return d

    def count_pop(c):
        if c <= 0:
            return 0
        res = 0
        ones = 0
        bl = n.bit_length()
        for i in range(bl - 1, -1, -1):
            if (n >> i) & 1:
                need = c - ones
                if 0 <= need <= i:
                    res += comb(i, need)
                ones += 1
        if ones == c:
            res += 1
        return res

    if k == 0:
        return 1 if n >= 1 else 0
    total = 0
    for c in range(1, 60):
        if depth(c) == k - 1:
            total += count_pop(c)
    if k == 1:
        total -= 1
    return total
